SELECT u.user_id as USERID, u.user_id, u.dept_id, u.nick_name, u.sync_user_id, u.maindepartment, u.user_name, u.user_type, u.email, u.avatar, u.phonenumber, u.password, u.sex, u.status, u.del_flag, u.login_ip, u.login_date, u.create_by, u.create_time, u.remark, t.dept_name AS dept_name FROM sys_user u join sys_dept t on u.dept_id =t.dept_id
/* JOIN uum_userinfo su ON u.`user_name`=su.`USERID` JOIN uum_organizationinfo g ON g.`OUGUID`=su.`OUGUID` JOIN sys_sync_dep d ON d.`sync_dep_id`=g.`OUGUID`*/ WHERE u.del_flag = '0'
AND (u.user_name like concat('%', #{userName}, '%') or u.nick_name like concat('%', #{userName}, '%') )
AND u.status = #{status}
AND u.phonenumber like concat('%', #{phonenumber}, '%')
AND date_format(u.create_time,'%y%m%d') >= date_format(#{beginTime},'%y%m%d')
AND date_format(u.create_time,'%y%m%d') <= date_format(#{endTime},'%y%m%d')
AND t.dept_id like concat('%', #{deptName}, '%')
AND t.dept_id =#{deptId}
AND (u.create_by =#{createBy} or u.user_name like concat('%', #{userName}, '%'))

