update sys_user
dept_id = #{deptId}, user_name = #{userName}, nick_name = #{nickName}, sync_user_id = #{syncUserId}, maindepartment = #{maindepartment}, user_type = #{userType}, email = #{email}, phonenumber = #{phonenumber}, sex = #{sex}, avatar = #{avatar}, password = #{password}, status = #{status}, login_ip = #{loginIp}, login_date = #{loginDate}, update_by = #{updateBy}, remark = #{remark}, id_Card_No = #{idCardNo}, update_time = sysdate()
where user_id = #{userId}

