select * from view_user_info u

    
        
            AND u.roleId = #{roleId}
        
    
    
        
            AND u.roleId IN (
            SELECT role_id from sys_user_role sr where sr.user_id IN(
            select user_id FROM sys_user s where s.user_name = #{userName}
            ) AND sr.role_id = #{roleId}
            )
        
    
    
        AND u.dept_id = #{deptId}
    
    
        AND u.orgName = #{company} AND u.orgLv = '1'

		SELECT u.* FROM sys_user u ,sys_user_role r
		  WHERE u.`user_id`=r.`user_id` AND u.`status`='0' AND u.`del_flag`='0'
		  AND r.`role_id` = #{roleId}

SELECT u.* FROM sys_user u ,sys_user_post r
  WHERE u.`user_id`=r.`user_id`
  AND r.`post_id` = #{postId}

select distinct u.user_id, u.dept_id, u.user_name as login_name, u.nick_name as user_name, u.user_type, u.email, u.avatar, u.phonenumber, u.status, u.create_time from sys_user u left join sys_dept d on u.dept_id = d.dept_id left join sys_user_role ur on u.user_id = ur.user_id left join sys_role r on r.role_id = ur.role_id where u.del_flag = '0' and r.role_id = #{roleId}
AND u.login_name like concat('%', #{loginName}, '%')
AND u.phonenumber like concat('%', #{phonenumber}, '%')
